python3 - <<'PY'
import json,re,subprocess
out={}
for name in ('debug-ai-debug-ai-1','astera-v8','astera-v8-evaluator'):
 p=subprocess.run(['docker','inspect',name],capture_output=True,text=True,timeout=10)
 if p.returncode!=0:out[name]={'status':'MISSING'};continue
 item=json.loads(p.stdout)[0]
 names={}
 for entry in (item.get('Config') or {}).get('Env') or []:
  var,sep,val=entry.partition('=')
  if not sep:continue
  if re.search(r'(CORE|MODEL|LLAMA|OPENAI|PROVIDER|BASE_URL|API_URL|ENDPOINT|INFERENCE|ROUTER)',var,re.I):
   if re.search(r'(KEY|TOKEN|PASS|SECRET|CRED|AUTH)',var,re.I):
    names[var]={'declared':bool(val),'value':'REDACTED'}
   elif re.search(r'(URL|HOST|PORT|ENDPOINT)',var,re.I):
    from urllib.parse import urlsplit
    try:
     addr=urlsplit(val)
     names[var]={'scheme':addr.scheme,'host':addr.hostname,'port':addr.port} if addr.hostname else {'configured':bool(val),'value_hidden':True}
    except Exception:names[var]={'configured':bool(val),'value_hidden':True}
   else:names[var]={'configured':bool(val),'value_hidden':True}
 logs=subprocess.run(['docker','logs','--tail','200',name],capture_output=True,text=True,timeout=15)
 tail=logs.stdout+'\n'+logs.stderr
 out[name]={'state':item.get('State',{}).get('Status'),'network':item.get('HostConfig',{}).get('NetworkMode'),'relevant_environment':names,'log_counts':{'old_18080':tail.count('18080'),'new_gate_ports':sum(tail.count(str(n)) for n in (18181,18182,18183,18184))},'secret_values_included':False}
body='AI_CORE_CONSUMER_LIVE_ENDPOINT_OWNERSHIP\n'+json.dumps(out,ensure_ascii=False,indent=2)
r=subprocess.run(['gh','api','-X','POST','repos/G-ACE-inc/server-core/issues/10/comments','--input','-','--jq','.html_url'],input=json.dumps({'body':body}),capture_output=True,text=True,timeout=22)
print('AI_CORE_CONSUMER_ENDPOINTS='+('PASS '+r.stdout.strip() if r.returncode==0 else 'POST_FAILED'))
raise SystemExit(0 if r.returncode==0 else 1)
